22	const sum = (amounts: number[]): number =>
23	  amounts.reduce((total, amount) => total + amount, 0);
24	
25	const PROCESSING_FEE = 5;
26	
27	// Binary floating point makes exact multiples land a hair off (100 * 1.1 + 5 =
28	// 115.00000000000001); snap to cent precision so only genuine fractions round up.
29	const roundUpInMHPCOsFavour = (amount: number): number =>
30	  Math.ceil(Number(amount.toFixed(6)));
31	
32	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
33	  sword: 100,
34	  amulet: 60,
35	  staff: 80,
36	  potion: 40,
37	  rune: 25,
38	  moonstone: 25,
39	};
40	
41	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
42	
43	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
44	
45	const BLOCK_SIZE = 3;
46	const BLOCK_BASE_PREMIUM = 60;
47	
48	const groupByType = (items: Item[]): Item[][] => {
49	  const itemsByType = new Map<string, Item[]>();
50	
51	  for (const item of items) {
52	    const sameTypeItems = itemsByType.get(item.type);
53	    if (sameTypeItems) sameTypeItems.push(item);
54	    else itemsByType.set(item.type, [item]);
55	  }
56	
57	  return [...itemsByType.values()];
58	};
59	
60	const COMPONENT_TYPES = ["rune", "moonstone"];
61	
62	const isComponent = (item: Item): boolean =>
63	  COMPONENT_TYPES.includes(item.type);
64	
65	// A block is a special price for exactly 3 alike components; any other count,
66	// and any main item, is charged per item.
67	const sameTypeBasePremiumOf = (sameTypeItems: Item[]): number =>
68	  sameTypeItems.length === BLOCK_SIZE && isComponent(sameTypeItems[0])
69	    ? BLOCK_BASE_PREMIUM
70	    : sum(sameTypeItems.map(basePremiumOf));
71	
72	const policyBasePremiumOf = (items: Item[]): number =>
73	  sum(groupByType(items).map(sameTypeBasePremiumOf));
74	
75	const quote = (step: QuoteStep): number => {
76	  const policyBasePremium = policyBasePremiumOf(step.items);
77	  const firstInsuranceSurcharge =
78	    policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
79	
80	  return roundUpInMHPCOsFavour(
81	    policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE,
82	  );
83	};
84	
85	export const runScenario = (scenario: Scenario): ScenarioResults => {
86	  return { results: scenario.steps.map((step) => ({ premium: quote(step) })) };
87	};
