// One entry per insurable type: every fact the office knows about a type lives
// here, so adding a type is a single edit.
type ItemKind = {
  basePremium: number;
  isComponent: boolean;
};

const ITEM_CATALOGUE: Record<string, ItemKind> = {
  sword: { basePremium: 100, isComponent: false },
  amulet: { basePremium: 60, isComponent: false },
  staff: { basePremium: 80, isComponent: false },
  potion: { basePremium: 40, isComponent: false },
  rune: { basePremium: 25, isComponent: true },
  moonstone: { basePremium: 25, isComponent: true },
};

const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const kindOf = (item: Item): ItemKind => ITEM_CATALOGUE[item.type];

const basePremiumOf = (item: Item): number => kindOf(item).basePremium;

